import { createClient } from '@typeform/api-client';

const typeformClient = createClient({
  token: process.env.TYPEFORM_API_TOKEN!,
});

const FORM_ID = 'your-form-id';

interface TypeformResponse {
  response_id: string;
  submitted_at: string;
  answers: Array<{
    field: { id: string; type: string };
    type: string;
    text?: string;
    choice?: { label: string };
    number?: number;
  }>;
}

async function getFormResponses(): Promise<void> {
  const result = await typeformClient.responses.list({
    uid: FORM_ID,
    pageSize: 100,
    sort: 'submitted_at,desc',
  });

  console.log(`Total responses: ${result.total_items}`);

  for (const response of result.items as TypeformResponse[]) {
    console.log(`Response ID: ${response.response_id}`);
    console.log(`Submitted at: ${response.submitted_at}`);

    for (const answer of response.answers) {
      const value = answer.text ?? answer.choice?.label ?? answer.number ?? 'N/A';
      console.log(`  Field ${answer.field.id} (${answer.type}): ${value}`);
    }
  }
}

getFormResponses().catch(console.error);

import express, { Request, Response } from 'express';
import crypto from 'crypto';

const app = express();

// Use raw body parser to allow signature verification
app.use(
  '/webhooks/typeform',
  express.raw({ type: 'application/json' })
);

interface TypeformWebhookPayload {
  form_response: {
    form_id: string;
    token: string;
    submitted_at: string;
    answers: Array<{
      field: { id: string; ref: string; type: string };
      type: string;
      text?: string;
      email?: string;
      choice?: { label: string };
    }>;
  };
}

function verifyTypeformSignature(
  rawBody: Buffer,
  signatureHeader: string,
  secret: string
): boolean {
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(rawBody);
  const digest = `sha256=${hmac.digest('base64')}`;
  return crypto.timingSafeEqual(
    Buffer.from(digest),
    Buffer.from(signatureHeader)
  );
}

app.post('/webhooks/typeform', (req: Request, res: Response): void => {
  const signature = req.headers['typeform-signature'] as string;
  const webhookSecret = process.env.TYPEFORM_WEBHOOK_SECRET!;

  if (!signature || !verifyTypeformSignature(req.body as Buffer, signature, webhookSecret)) {
    res.status(401).json({ error: 'Invalid signature' });
    return;
  }

  // Return 200 immediately before processing
  res.status(200).json({ received: true });

  const payload = JSON.parse((req.body as Buffer).toString()) as TypeformWebhookPayload;
  const { form_response } = payload;

  console.log(`Form submission received for form: ${form_response.form_id}`);
  console.log(`Submission token: ${form_response.token}`);
  console.log(`Submitted at: ${form_response.submitted_at}`);

  for (const answer of form_response.answers) {
    const value = answer.text ?? answer.email ?? answer.choice?.label ?? 'N/A';
    console.log(`  [${answer.field.ref}]: ${value}`);
  }
});

app.listen(3000, () => console.log('Webhook server running on port 3000'));
